// Original ambient score: slow pads, a sparse melody and two stereo delays.
export class SpaceMusic{
 constructor(context){this.context=context;this.output=context.createGain();this.output.gain.value=0;this.output.connect(context.destination);this.running=false;this.step=0;const left=context.createDelay(2),right=context.createDelay(2),feedback=context.createGain(),wet=context.createGain();left.delayTime.value=.61;right.delayTime.value=.89;feedback.gain.value=.25;wet.gain.value=.24;this.output.connect(left);left.connect(right);right.connect(feedback);feedback.connect(left);right.connect(wet);wet.connect(context.destination);}
 note(midi,start,duration,volume,type='sine'){const c=this.context,o=c.createOscillator(),g=c.createGain(),filter=c.createBiquadFilter();o.type=type;o.frequency.value=440*2**((midi-69)/12);filter.type='lowpass';filter.frequency.value=1100;g.gain.setValueAtTime(0,start);g.gain.linearRampToValueAtTime(volume,start+1.8);g.gain.setValueAtTime(volume*.65,start+duration*.65);g.gain.linearRampToValueAtTime(0,start+duration);o.connect(filter).connect(g).connect(this.output);o.start(start);o.stop(start+duration+.1);o.onended=()=>{o.disconnect();filter.disconnect();g.disconnect();};}
 schedule(){if(!this.running)return;const c=this.context,start=c.currentTime+.15,chords=[[45,52,57,60,64],[41,48,57,60,64],[48,55,59,62,67],[40,47,55,59,64]],melody=[[76,79,76,72],[76,72,69,72],[74,79,83,79],[76,71,67,71]],i=this.step++%4;for(const n of chords[i])this.note(n,start,15,n<50?.13:.055,'sine');melody[i].forEach((n,j)=>this.note(n,start+j*3,6,.04));this.timer=setTimeout(()=>this.schedule(),12000);}
 set(enabled){if(enabled&&!this.running){this.running=true;this.schedule();}this.output.gain.setTargetAtTime(enabled?.18:0,this.context.currentTime,1.4);}
}
